flex-direction: column;
z-index: 5;
box-sizing: border-box;
padding: 0;
gap: 8px;
}
.hot-posts .post-tag, .PopularPosts .hot-posts .post-tag{
position:relative;
height: auto;
display: flex;
width: -moz-fit-content;
width: fit-content;
font-size: 13px;
font-weight: 500;
padding:0;
margin: 0;
box-sizing: border-box;
