}
.hot-posts .post-title a, .PopularPosts .hot-posts .post-title a{
color:var(--c-title);
display: -webkit-box;
-webkit-line-clamp: 2;
-webkit-box-orient: vertical;
overflow: hidden;
}
.hot-posts .post-title a:hover, .PopularPosts .hot-posts .post-title a:hover{
color:#0AF8C5
}
