head.script:
//
const noThumbnail = "data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%20160%2090%22%20preserveAspectRatio%3D%22xMidYMid%20slice%22%3E%3Crect%20width%3D%22160%22%20height%3D%2290%22%20fill%3D%22%23e5e7eb%22%2F%3E%3Ccircle%20cx%3D%2250%22%20cy%3D%2235%22%20r%3D%227%22%20fill%3D%22%239ca3af%22%2F%3E%3Cpath%20d%3D%22M20%2075L60%2045L80%2060L110%2035L150%2075Z%22%20fill%3D%22%239ca3af%22%2F%3E%3C%2Fsvg%3E";
const postPerPage = 7;
const fixedSidebar = true;
//

//
(function () {
  try {
    var t = localStorage.getItem('ten-theme');
    if (t !== 'dark' && t !== 'light') {
      t = window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
    }
    document.documentElement.setAttribute('data-theme', t);
  } catch (e) {
    document.documentElement.setAttribute('data-theme', 'light');
  }
})();
//

body.script:
//
(function () {

  // ----- Animation helpers (replace jQuery fade/slide) -----
  function fadeIn(el, ms) {
    ms = ms || 250;
    if (el._anim) clearTimeout(el._anim);
    el.style.display = '';
    el.style.opacity = '0';
    el.style.transition = 'opacity ' + ms + 'ms';
    void el.offsetWidth;  // force reflow so transition kicks in
    el.style.opacity = '1';
    el._anim = setTimeout(function () { el.style.transition = ''; }, ms);
  }
  function fadeOut(el, ms) {
    ms = ms || 250;
    if (el._anim) clearTimeout(el._anim);
    el.style.transition = 'opacity ' + ms + 'ms';
    el.style.opacity = '0';
    el._anim = setTimeout(function () {
      el.style.display = 'none';
      el.style.opacity = '';
      el.style.transition = '';
    }, ms);
  }
  function fadeToggle(el, ms) {
    if (getComputedStyle(el).display === 'none') fadeIn(el, ms);
    else fadeOut(el, ms);
  }
  function slideDown(el, ms) {
    ms = ms || 170;
    if (el._anim) clearTimeout(el._anim);
    el.style.display = '';
    var h = el.scrollHeight;
    el.style.overflow = 'hidden';
    el.style.height = '0px';
    el.style.transition = 'height ' + ms + 'ms';
    void el.offsetWidth;
    el.style.height = h + 'px';
    el._anim = setTimeout(function () {
      el.style.height = '';
      el.style.overflow = '';
      el.style.transition = '';
    }, ms);
  }
  function slideUp(el, ms) {
    ms = ms || 170;
    if (el._anim) clearTimeout(el._anim);
    el.style.overflow = 'hidden';
    el.style.height = el.scrollHeight + 'px';
    el.style.transition = 'height ' + ms + 'ms';
    void el.offsetWidth;
    el.style.height = '0px';
    el._anim = setTimeout(function () {
      el.style.display = 'none';
      el.style.height = '';
      el.style.overflow = '';
      el.style.transition = '';
    }, ms);
  }
  function slideToggle(el, ms) {
    if (getComputedStyle(el).display === 'none') slideDown(el, ms);
    else slideUp(el, ms);
  }

  function ready(fn) {
    if (document.readyState !== 'loading') fn();
    else document.addEventListener('DOMContentLoaded', fn);
  }

  ready(function () {

    // ----- Main menu: Blogger's LinkList widget renders a flat <ul>. Walk the
    //       siblings and re-parent items whose label starts with '_' (level 2)
    //       or '__' (level 3) so the CSS dropdown rules have a nested tree to
    //       hang off. The prefix underscores are stripped from the visible text.
    document.querySelectorAll('#main-menu').forEach(function (menu) {
      var nav = menu.querySelector('ul#main-menu-nav');
      if (!nav) return;
      var lastTop = null, lastSub = null;
      Array.from(nav.children).forEach(function (li) {
        if (li.tagName !== 'LI') return;
        var a = li.querySelector(':scope > a');
        if (!a) return;
        var label = a.textContent;
        var depth = 0;
        while (label.charAt(0) === '_') { depth++; label = label.substring(1); }
        if (depth === 0) { lastTop = li; lastSub = null; return; }
        a.textContent = label;
        var parent = depth === 1 ? lastTop : lastSub;
        if (!parent) return;
        var subUl = parent.querySelector(':scope > ul.sub-menu');
        if (!subUl) {
          subUl = document.createElement('ul');
          subUl.className = 'sub-menu';
          parent.appendChild(subUl);
          parent.classList.add('has-sub');
        }
        subUl.appendChild(li);
        if (depth === 1) lastSub = li;
      });
      menu.querySelectorAll('.widget').forEach(function (w) { w.classList.add('show-menu'); });
    });

    // Clone desktop nav into mobile menu container and add submenu toggles.
    var srcNav = document.getElementById('main-menu-nav');
    if (srcNav) {
      document.querySelectorAll('.mobile-menu').forEach(function (mob) {
        mob.appendChild(srcNav.cloneNode(true));
      });
    }
    document.querySelectorAll('.mobile-menu .has-sub').forEach(function (p) {
      var t = document.createElement('div');
      t.className = 'submenu-toggle';
      p.appendChild(t);
    });

    // Rewrite mega-menu top-level items to category search URLs.
    document.querySelectorAll('.mobile-menu ul > li a').forEach(function (a) {
      var classes = a.getAttribute('class') || '';
      if (/mega-menu/.test(classes)) {
        a.setAttribute('href', '/search/label/' + encodeURIComponent(a.textContent) + '?&max-results=' + postPerPage);
      }
    });

    // ----- UI toggles -----
    document.querySelectorAll('.mobile-menu-toggle').forEach(function (btn) {
      btn.addEventListener('click', function () {
        document.body.classList.toggle('nav-active');
      });
    });

    document.querySelectorAll('.mobile-menu ul li .submenu-toggle').forEach(function (toggle) {
      toggle.addEventListener('click', function (e) {
        e.preventDefault();
        var parent = toggle.parentElement;
        var sub = parent.querySelector(':scope > .sub-menu');
        parent.classList.toggle('show');
        if (sub) slideToggle(sub, 170);
      });
    });


    // ----- Label/tag links: append max-results so paginated label pages work.
    //       Idempotent — skip if already appended (handles script re-execution).
    document.querySelectorAll('.Label a, a.b-label, a.post-tag').forEach(function (a) {
      var href = a.getAttribute('href');
      if (href && href.indexOf('max-results=') === -1) {
        a.setAttribute('href', href + '?&max-results=' + postPerPage);
      }
    });

    // ----- Author description links open in new tab.
    document.querySelectorAll('.author-description a').forEach(function (a) {
      a.setAttribute('target', '_blank');
    });

    // ----- Counter widget animation: count from 0 up to the rendered number
    //       when the element scrolls into view.
    document.querySelectorAll('.counter-info .counter-title').forEach(function (el) {
      var raw = el.textContent.trim();
      var target = parseFloat(raw.replace(/[^0-9.\-]/g, ''));
      if (!isFinite(target)) return;
      var hasComma = /,/.test(raw);
      var format = function (n) {
        var s = String(Math.round(n));
        return hasComma ? s.replace(/\B(?=(\d{3})+(?!\d))/g, ',') : s;
      };
      el.textContent = format(0);
      var observer = new IntersectionObserver(function (entries) {
        entries.forEach(function (entry) {
          if (!entry.isIntersecting) return;
          observer.disconnect();
          var duration = 3000, started = null;
          requestAnimationFrame(function tick(now) {
            if (started === null) started = now;
            var p = Math.min((now - started) / duration, 1);
            var eased = 1 - Math.pow(1 - p, 3);  // ease-out cubic
            el.textContent = format(eased * target);
            if (p < 1) requestAnimationFrame(tick);
          });
        });
      }, { threshold: 0.5 });
      observer.observe(el);
    });

    // ----- Per-post sidebar position markers: a <strike>left-sidebar</strike>,
    //       <strike>right-sidebar</strike>, or <strike>full-width</strike> inside
    //       a post body swaps the wrapper layout for that post.
    document.querySelectorAll('.post-body strike').forEach(function (el) {
      var marker = el.textContent;
      var rule = null;
      if (marker.indexOf('left-sidebar') !== -1) {
        rule = '.item #main-wrapper{float:right}.item #sidebar-wrapper{float:left}';
      } else if (marker.indexOf('right-sidebar') !== -1) {
        rule = '.item #main-wrapper{float:left}.item #sidebar-wrapper{float:right}';
      } else if (marker.indexOf('full-width') !== -1) {
        rule = '.item #main-wrapper{width:100%}.item #sidebar-wrapper{display:none}';
      }
      if (rule !== null) {
        var s = document.createElement('style');
        s.textContent = rule;
        el.parentNode.replaceChild(s, el);
      }
    });

    // ----- Sticky sidebar: posts follow as you scroll. Gated on `fixedSidebar`
    //       (defined in the Global Variables script above). Shifts the sidebar
    //       with `top:` during scroll so it stays in its column without needing
    //       a flex/grid container.
    if (typeof fixedSidebar !== 'undefined' && fixedSidebar === true) {
      var sidebar = document.getElementById('sidebar-wrapper');
      var main = document.getElementById('main-wrapper');
      if (sidebar && main) {
        var marginTop = 30, marginBottom = 30;
        sidebar.style.position = 'relative';
        var rafPending = false;
        var update = function () {
          rafPending = false;
          if (sidebar.offsetHeight >= main.offsetHeight) {
            sidebar.style.top = '';
            return;
          }
          var mainTop = main.getBoundingClientRect().top + window.scrollY;
          var maxOffset = main.offsetHeight - sidebar.offsetHeight - marginBottom;
          var scrolled = window.scrollY + marginTop - mainTop;
          sidebar.style.top = Math.max(0, Math.min(scrolled, maxOffset)) + 'px';
        };
        var schedule = function () {
          if (rafPending) return;
          rafPending = true;
          requestAnimationFrame(update);
        };
        window.addEventListener('scroll', schedule, { passive: true });
        window.addEventListener('resize', schedule);
        // Recalc on element-size change so late-loading images don't leave the
        // sticky position stale; ResizeObserver fires after layout settles.
        if (typeof ResizeObserver !== 'undefined') {
          var ro = new ResizeObserver(schedule);
          ro.observe(main);
          ro.observe(sidebar);
        } else {
          // Fallback: re-run after window load (covers most image-loading cases).
          window.addEventListener('load', schedule);
        }
        update();
      }
    }

    // ----- Back to top: show after scrolling 100px, smooth-scroll to top on click.
    //       Single scroll handler updates all .back-top buttons.
    var backTopBtns = document.querySelectorAll('.back-top');
    if (backTopBtns.length) {
      var btnVisible = false;  // .back-top starts as display:none via CSS
      window.addEventListener('scroll', function () {
        var shouldShow = window.scrollY >= 100;
        if (shouldShow === btnVisible) return;
        btnVisible = shouldShow;
        backTopBtns.forEach(function (btn) {
          if (shouldShow) fadeIn(btn, 250); else fadeOut(btn, 250);
        });
      }, { passive: true });
      backTopBtns.forEach(function (btn) {
        btn.addEventListener('click', function () {
          window.scrollTo({ top: 0, behavior: 'smooth' });
        });
      });
    }

    // ----- Helper: HTML-escape strings inserted into generated markup.
    function esc(s) {
      return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) {
        return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
      });
    }

    // ----- Related posts: fetch a few posts sharing the post's first label via
    //       Blogger's JSON feed and render them under .related-ready.
    document.querySelectorAll('.related-ready').forEach(function (container) {
      var tag = container.querySelector('.related-tag');
      var label = tag ? tag.getAttribute('data-label') : null;
      var count = 3;
      var feedUrl = (label && label !== 'random')
        ? '/feeds/posts/default/-/' + encodeURIComponent(label) + '?alt=json&max-results=' + (count + 1)
        : '/feeds/posts/default?alt=json&max-results=' + count + '&orderby=published';
      fetch(feedUrl).then(function (r) { return r.json(); }).then(function (data) {
        var entries = (data.feed && data.feed.entry) || [];
        var currentPath = location.pathname;
        var items = [];
        for (var i = 0; i < entries.length && items.length < count; i++) {
          var entry = entries[i];
          var alt = (entry.link || []).filter(function (l) { return l.rel === 'alternate'; })[0];
          if (!alt) continue;
          if (alt.href.indexOf(currentPath) !== -1) continue;
          var thumb = (entry['media$thumbnail'] && entry['media$thumbnail'].url) || (typeof noThumbnail !== 'undefined' ? noThumbnail : '');
          // Bump default 72px thumbnail up to a usable size for the 120px block.
          thumb = thumb.replace(/\/s72-c\//, '/w320-h180-p-k-no-nu/');
          items.push({
            url: alt.href,
            title: (entry.title && entry.title.$t) || '',
            thumb: thumb,
          });
        }
        if (!items.length) { container.innerHTML = ''; return; }
        container.innerHTML =
          '<ul class="related-posts">' +
          items.map(function (it) {
            return '<li class="related-item">' +
                     '<a class="post-image-link" href="' + esc(it.url) + '">' +
                       '<img class="post-thumb" loading="lazy" src="' + esc(it.thumb) + '" alt="' + esc(it.title) + '"/>' +
                     '</a>' +
                     '<h4 class="post-title"><a href="' + esc(it.url) + '">' + esc(it.title) + '</a></h4>' +
                   '</li>';
          }).join('') +
          '</ul>';
      }).catch(function () { container.innerHTML = ''; });
    });

    // ----- Post navigation: fetch the prev/next post pages and extract their
    //       titles so the nav links can show what's coming/going. Uses
    //       DOMParser (no script execution) and only sets .textContent — no
    //       HTML injection — so the fetched HTML can't introduce DOM nodes.
    document.querySelectorAll('.post-nav').forEach(function (nav) {
      [
        { linkSel: '.prev-post-link', target: '.post-prev a .post-nav-inner p' },
        { linkSel: '.next-post-link', target: '.post-next a .post-nav-inner p' },
      ].forEach(function (cfg) {
        var link = nav.querySelector(cfg.linkSel) || document.querySelector(cfg.linkSel);
        var href = link ? link.getAttribute('href') : null;
        if (!href) return;
        fetch(href).then(function (r) { return r.text(); }).then(function (html) {
          var doc = new DOMParser().parseFromString(html, 'text/html');
          var titleEl = doc.querySelector('.blog-post h1.post-title');
          if (!titleEl) return;
          var targetEl = nav.querySelector(cfg.target) || document.querySelector(cfg.target);
          if (targetEl) targetEl.textContent = titleEl.textContent.trim();
        }).catch(function () { /* leave placeholder text as-is */ });
      });
    });

    // ----- Post label counts: data:post.labels carries no global post count,
    //       so fetch each distinct label's totalResults from the summary feed
    //       (max-results=0 downloads no entries) and append it to the tag.
    //       Distinct labels are fetched once and shared across duplicate links.
    (function () {
      var links = document.querySelectorAll('.post-labels a[rel="tag"]');
      if (!links.length) return;
      var pending = {};
      links.forEach(function (a) {
        var name = a.textContent.trim();
        if (!name) return;
        if (!pending[name]) {
          pending[name] = fetch('/feeds/posts/summary/-/' + encodeURIComponent(name) + '?alt=json&max-results=0')
            .then(function (r) { return r.json(); })
            .then(function (d) {
              var t = d.feed && d.feed.openSearch$totalResults && d.feed.openSearch$totalResults.$t;
              return t == null ? null : parseInt(t, 10);
            }).catch(function () { return null; });
        }
        pending[name].then(function (n) {
          if (n == null || isNaN(n)) return;
          var c = document.createElement('span');
          c.className = 'label-count';
          c.textContent = '(' + n + ')';
          a.appendChild(c);
        });
      });
    })();

    // ----- Comment form host fix: Blogger sometimes points the embedded comment
    //       editor iframe at draft.blogger.com, which won't load for visitors and
    //       leaves the comment box blank. Rewrite it (and the src anchor) to www.
    (function () {
      function toWww(u) { return u ? u.replace('://draft.blogger.com', '://www.blogger.com') : u; }
      var src = document.getElementById('comment-editor-src');
      if (src) src.href = toWww(src.getAttribute('href') || '');
      var ifr = document.getElementById('comment-editor');
      if (!ifr) return;
      function fix() {
        var s = ifr.getAttribute('src') || '';
        if (s.indexOf('draft.blogger.com') !== -1) ifr.src = toWww(s);
      }
      fix();
      try {
        var mo = new MutationObserver(fix);
        mo.observe(ifr, { attributes: true, attributeFilter: ['src'] });
        setTimeout(function () { mo.disconnect(); }, 8000);
      } catch (e) {
        var n = 0, iv = setInterval(function () { fix(); if (++n > 40) clearInterval(iv); }, 200);
      }
    })();


  });
})();
//

b:if.script:
//
// Pagination state. Globals are intentional — inline onclick handlers in the
// rendered pager need to call getPage/getLabelPage.
let postResults = postPerPage;
const PAGE_BLOCK = 10;
const pageOf = ["Page", "of"];
let noPage;
let currentPage;
let currentPageNo;
let postLabel;
const HOME = "/";

function buildLabelHref(page) {
  return `/search/label/${postLabel}?&max-results=${postResults}` + (page ? `#PageNo=${page}` : '');
}

// Pages are shown in fixed blocks of PAGE_BLOCK (1-10, 11-20, ...):
// « previous block, ‹ previous page, page numbers, › next page, » next block.
function startPagination(totalResults) {
  const cur = Number(currentPageNo) || 1;
  const lastPageNo = Math.max(1, Math.ceil(totalResults / postResults));
  const blockStart = Math.floor((cur - 1) / PAGE_BLOCK) * PAGE_BLOCK + 1;
  const blockEnd = Math.min(blockStart + PAGE_BLOCK - 1, lastPageNo);
  const fn = currentPage === 'page' ? 'getPage' : 'getLabelPage';
  const firstHref = currentPage === 'page' ? HOME : `/search/label/${postLabel}?&max-results=${postResults}`;
  const link = (page, cls, text, title) => {
    const t = title ? ` title="${title}"` : '';
    return page === 1
      ? `<a class="${cls}" href="${firstHref}"${t}>${text}</a>`
      : `<a class="${cls}" href="#" onclick="${fn}(${page});return false"${t}>${text}</a>`;
  };

  const parts = [];
  parts.push(`<span class="page-of">${pageOf[0]} ${cur} ${pageOf[1]} ${lastPageNo}</span>`);
  if (blockStart > 1) parts.push(link(blockStart - PAGE_BLOCK, 'page-num page-prev-block', '', `Pages ${blockStart - PAGE_BLOCK}-${blockStart - 1}`));
  if (cur > 1) parts.push(link(cur - 1, 'page-num page-prev', '', 'Previous page'));
  for (let d = blockStart; d <= blockEnd; d++) {
    parts.push(d === cur ? `<span class="page-num page-active">${d}</span>` : link(d, 'page-num', d));
  }
  if (cur < lastPageNo) parts.push(link(cur + 1, 'page-num page-next', '', 'Next page'));
  if (blockEnd < lastPageNo) parts.push(link(blockStart + PAGE_BLOCK, 'page-num page-next-block', '', `Pages ${blockStart + PAGE_BLOCK}-${Math.min(blockStart + 2 * PAGE_BLOCK - 1, lastPageNo)}`));

  const html = parts.join('');
  const areas = document.querySelectorAll('[name="pageArea"]');
  const pager = document.getElementById('blog-pager');
  areas.forEach(area => { area.innerHTML = html; });
  if (pager && areas.length === 0) pager.innerHTML = html;
}

function dataFeed(data) {
  const total = parseInt(data.feed.openSearch$totalResults.$t, 10);
  startPagination(total);
}

function pageCurrentBlogger() {
  const url = location.href;
  if (url.indexOf('/search/label/') !== -1) {
    const labelStart = url.indexOf('/search/label/') + 14;
    const labelEnd = url.indexOf('?updated-max') !== -1 ? url.indexOf('?updated-max') : url.indexOf('?&max');
    postLabel = url.substring(labelStart, labelEnd);
  }
  if (url.indexOf('?q=') !== -1 || url.indexOf('.html') !== -1) return;

  const pageNoIdx = url.indexOf('#PageNo=');
  currentPageNo = pageNoIdx !== -1 ? url.substring(pageNoIdx + 8) : 1;

  if (url.indexOf('/search/label/') === -1) {
    currentPage = 'page';
    fetchFeed(`${HOME}feeds/posts/summary?max-results=1&alt=json`).then(dataFeed);
  } else {
    currentPage = 'label';
    if (url.indexOf('&max-results=') === -1) postResults = 20;
    fetchFeed(`${HOME}feeds/posts/summary/-/${postLabel}?alt=json&max-results=1`).then(dataFeed);
  }
}

function fetchFeed(url) {
  return fetch(url).then(r => r.json());
}

function getPage(page) {
  const jsonstart = (page - 1) * postResults;
  noPage = page;
  fetchFeed(`${HOME}feeds/posts/summary?start-index=${jsonstart}&max-results=1&alt=json`).then(findPostDate);
}

function getLabelPage(page) {
  const jsonstart = (page - 1) * postResults;
  noPage = page;
  fetchFeed(`${HOME}feeds/posts/summary/-/${postLabel}?start-index=${jsonstart}&max-results=1&alt=json`).then(findPostDate);
}

function findPostDate(data) {
  const post = data.feed.entry[0];
  const ts = encodeURIComponent(post.published.$t.substring(0, 19) + post.published.$t.substring(23, 29));
  const url = currentPage === 'page'
    ? `/search?updated-max=${ts}&max-results=${postResults}#PageNo=${noPage}`
    : `/search/label/${postLabel}?updated-max=${ts}&max-results=${postResults}#PageNo=${noPage}`;
  location.href = url;
}

pageCurrentBlogger();
//

body.script:
//
(function () {
  var PLACEHOLDER = 'data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%20160%2090%22%20preserveAspectRatio%3D%22xMidYMid%20slice%22%3E%3Crect%20width%3D%22160%22%20height%3D%2290%22%20fill%3D%22%23e5e7eb%22%2F%3E%3Ccircle%20cx%3D%2250%22%20cy%3D%2235%22%20r%3D%227%22%20fill%3D%22%239ca3af%22%2F%3E%3Cpath%20d%3D%22M20%2075L60%2045L80%2060L110%2035L150%2075Z%22%20fill%3D%22%239ca3af%22%2F%3E%3C%2Fsvg%3E';

  // ----- Shared: load every post from the summary feed once -----
  var allPostsPromise = null;
  function fetchAll() {
    if (allPostsPromise) return allPostsPromise;
    function page(start, acc) {
      return fetch('/feeds/posts/summary?alt=json&max-results=150&start-index=' + start)
        .then(function (r) { return r.json(); })
        .then(function (data) {
          var entries = (data.feed && data.feed.entry) || [];
          acc = acc.concat(entries);
          return entries.length === 150 ? page(start + 150, acc) : acc;
        });
    }
    allPostsPromise = page(1, []);
    return allPostsPromise;
  }
  function isArchive(e) {
    return (e.category || []).some(function (c) { return c.term === 'Archive'; });
  }
  function postHref(e) {
    var link = (e.link || []).filter(function (l) { return l.rel === 'alternate'; })[0];
    return link ? link.href.replace(/^https?:\/\/[^/]+/, '') : '#';
  }
  function postDate(e) {
    return new Date(e.published.$t).toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' });
  }
  function esc(s) {
    return String(s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }

  // ----- Dark mode toggle -----
  function setupThemeToggle() {
    var host = document.querySelector('#header-wrap .container');
    if (!host || document.querySelector('.theme-toggle')) return;
    var btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'theme-toggle';
    btn.setAttribute('aria-label', 'Toggle dark mode');
    btn.innerHTML =
      '<svg class="icon-moon" viewBox="0 0 24 24"><path d="M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z"/></svg>' +
      '<svg class="icon-sun" viewBox="0 0 24 24"><circle cx="12" cy="12" r="5"/><path d="M12 1v2M12 21v2M4.22 4.22l1.42 1.42M18.36 18.36l1.42 1.42M1 12h2M21 12h2M4.22 19.78l1.42-1.42M18.36 5.64l1.42-1.42"/></svg>';
    btn.addEventListener('click', function () {
      var next = document.documentElement.getAttribute('data-theme') === 'dark' ? 'light' : 'dark';
      document.documentElement.setAttribute('data-theme', next);
      try { localStorage.setItem('ten-theme', next); } catch (e) {}
    });
    host.appendChild(btn);
  }

  // ----- Tags widget: top tags first, the rest behind "Show all" -----
  function setupTags() {
    var cloud = document.querySelector('.widget.Label .cloud-label');
    if (!cloud) return;
    var ul = cloud.querySelector('ul');
    if (!ul) return;
    var TOP = 20;
    var items = Array.prototype.slice.call(ul.children).map(function (li) {
      var countEl = li.querySelector('.label-count');
      var count = countEl ? parseInt(countEl.textContent.replace(/[^0-9]/g, ''), 10) || 0 : 0;
      var a = li.querySelector('a');
      var name = a ? a.childNodes[0].textContent.trim() : '';
      return { li: li, count: count, name: name };
    });
    if (items.length <= TOP) return;
    items.sort(function (x, y) { return y.count - x.count || x.name.localeCompare(y.name); });
    items.forEach(function (it, i) {
      ul.appendChild(it.li);
      if (i >= TOP) it.li.classList.add('tag-hidden');
    });

    var tools = document.createElement('div');
    tools.className = 'tag-tools';
    var input = document.createElement('input');
    input.type = 'search';
    input.placeholder = 'Filter tags';
    var btn = document.createElement('button');
    btn.type = 'button';
    function label() {
      btn.textContent = cloud.classList.contains('show-all') ? 'Show fewer tags' : 'Show all ' + items.length + ' tags';
    }
    function filter() {
      var q = input.value.trim().toLowerCase();
      items.forEach(function (it) {
        it.li.classList.toggle('tag-filtered', q !== '' && it.name.toLowerCase().indexOf(q) === -1);
      });
    }
    label();
    btn.addEventListener('click', function () {
      cloud.classList.toggle('show-all');
      if (!cloud.classList.contains('show-all')) { input.value = ''; filter(); }
      label();
    });
    input.addEventListener('input', filter);
    tools.appendChild(input);
    tools.appendChild(btn);
    cloud.parentNode.insertBefore(tools, cloud.nextSibling);
  }

  // ----- Sidebar: replace Popular Posts with a personal stats card -----
  // Edit this object to update the card.
  // Developer since May 2020, with a ~100-day break in between.
  var DEV_START = new Date(2020, 4, 1);
  var DEV_BREAK_DAYS = 100;
  function devYearOrdinal() {
    var days = (Date.now() - DEV_START.getTime()) / 86400000 - DEV_BREAK_DAYS;
    var n = Math.floor(days / 365.25) + 1; // Korean-style: 7th year = 6.x years done
    var s = ['th', 'st', 'nd', 'rd'], v = n % 100;
    return { n: n, suffix: s[(v - 20) % 10] || s[v] || s[0] };
  }

  var MY_STATS = {
    tiles: [
      { num: '-', unit: '', label: 'As a developer', auto: 'devYear' },
      { num: '-', unit: '', label: 'Posts written', auto: 'posts' }
    ],
    rows: [
      { label: 'Role', value: 'Backend → Product Engineer' },
      { label: 'Based in', value: 'Fukuoka, Japan' },
      { label: 'Speaks', value: 'Korean · Japanese · English' }
    ],
  };

  function setupMyStats() {
    var widget = document.querySelector('.widget.PopularPosts');
    if (!widget) return;
    var title = widget.querySelector('.widget-title .title, .widget-title h3, h3.title');
    if (title) title.textContent = 'My Stats';
    var content = widget.querySelector('.widget-content') || widget;
    var s = MY_STATS;
    content.innerHTML =
      "<div class='blog-stats'>" + s.tiles.map(function (t) {
        return "<div class='stat-tile'><span class='stat-num'" + (t.auto ? " data-auto='" + t.auto + "'" : '') + ">" + esc(t.num) + (t.unit ? "<small>" + esc(t.unit) + '</small>' : '') + "</span><span class='stat-label'>" + esc(t.label) + '</span></div>';
      }).join('') + '</div>' +
      "<ul class='stats-meta'>" + s.rows.map(function (r) {
        return '<li><span>' + esc(r.label) + '</span><b>' + esc(r.value) + '</b></li>';
      }).join('') + '</ul>';
    var devEl = content.querySelector("[data-auto='devYear']");
    if (devEl) { var dy = devYearOrdinal(); devEl.innerHTML = dy.n + '<small>' + dy.suffix + ' year</small>'; }
    var postsEl = content.querySelector("[data-auto='posts']");
    if (postsEl) fetchAll().then(function (entries) { postsEl.textContent = entries.length; }).catch(function () {});
  }

  // ----- "Hide archive" view: /?posts=current[&page=N] -----
  // The summary feed has no thumbnails for externally hosted images, so the
  // first image of each post on the current page is looked up separately.
  var thumbCache = {};
  function postId(e) {
    var m = /post-(\d+)$/.exec(e.id.$t);
    return m ? m[1] : '';
  }
  function loadThumb(e) {
    var id = postId(e);
    if (e.media$thumbnail) {
      return Promise.resolve(e.media$thumbnail.url.replace(/\/s72-c\//, '/w640-h360-p-k-no-nu/').replace(/=s72-c$/, '=w640-h360-p-k-no-nu'));
    }
    if (!id) return Promise.resolve(PLACEHOLDER);
    if (thumbCache[id]) return thumbCache[id];
    thumbCache[id] = fetch('/feeds/posts/default/' + id + '?alt=json')
      .then(function (r) { return r.json(); })
      .then(function (d) {
        var html = (d.entry && d.entry.content && d.entry.content.$t) || '';
        var m = /<img[^>]+src=["']([^"']+)["']/i.exec(html);
        return m ? m[1] : PLACEHOLDER;
      })
      .catch(function () { return PLACEHOLDER; });
    return thumbCache[id];
  }

  function card(e, thumb) {
    var href = postHref(e);
    var title = e.title.$t;
    var tag = (e.category || []).filter(function (c) { return c.term !== 'Archive'; })[0];
    tag = tag ? tag.term : '';
    var snippet = e.summary ? e.summary.$t.slice(0, 120) : '';
    var author = (e.author && e.author[0] && e.author[0].name && e.author[0].name.$t) || '';
    return "<div class='blog-post hentry index-post'><div class='index-post-inside-wrap'>" +
      "<div class='post-image-wrap'><a class='post-image-link' href='" + esc(href) + "'><img alt='" + esc(title) + "' class='post-thumb' loading='lazy' src='" + esc(thumb) + "'/></a></div>" +
      "<div class='post-info-wrap'><div class='post-info'>" +
      (tag ? "<a class='post-tag' href='/search/label/" + encodeURIComponent(tag) + "'>" + esc(tag) + "</a>" : '') +
      "<h2 class='post-title'><a href='" + esc(href) + "'>" + esc(title) + "</a></h2></div>" +
      "<div class='index-post-footer'><div class='post-meta'>" +
      (author ? "<span class='post-author'>" + esc(author) + "</span>" : '') +
      "<span class='post-date published'>" + esc(postDate(e)) + "</span></div>" +
      "<p class='post-snippet'>" + esc(snippet) + "</p><a class='read-more' href='" + esc(href) + "'>Read more</a></div>" +
      "</div></div></div>";
  }

  // Numbered pager using the theme's own .blog-pager / .page-num styles.
  function pagerHtml(page, pages) {
    if (pages <= 1) return '';
    var out = [];
    var link = function (n, cls, text) {
      return "<a class='page-num" + (cls ? ' ' + cls : '') + "' href='?posts=current&amp;page=" + n + "' data-page='" + n + "'>" + (text || '') + '</a>';
    };
    if (page > 1) out.push(link(page - 1, 'page-prev'));
    var shown = {};
    [1, page - 1, page, page + 1, pages].forEach(function (n) { if (n >= 1 && n <= pages) shown[n] = true; });
    var last = 0;
    Object.keys(shown).map(Number).sort(function (a, b) { return a - b; }).forEach(function (n) {
      if (n - last > 1) out.push("<span class='page-num page-dots'>...</span>");
      out.push(n === page ? "<span class='page-num page-active'>" + n + '</span>' : link(n, '', String(n)));
      last = n;
    });
    if (page < pages) out.push(link(page + 1, 'page-next'));
    return out.join('');
  }

  function setupFilterView() {
    var params = new URLSearchParams(location.search);
    if (params.get('posts') !== 'current') return;
    var grid = document.querySelector('.blog-posts .grid-posts');
    if (!grid) return;
    var PAGE = grid.querySelectorAll('.index-post').length || 7;
    // Hide the theme's pager (its script may rewrite it) and use our own.
    var themePager = document.getElementById('blog-pager');
    if (themePager) themePager.style.display = 'none';
    var pager = document.createElement('div');
    pager.className = 'blog-pager container';
    pager.id = 'hide-archive-pager';
    grid.parentNode.insertBefore(pager, grid.nextSibling);
    grid.innerHTML = '';
    var note = document.createElement('p');
    note.className = 'filter-note';
    note.textContent = 'Loading posts...';
    grid.parentNode.insertBefore(note, grid);

    fetchAll().then(function (entries) {
      var list = entries.filter(function (e) { return !isArchive(e); });
      var pages = Math.max(1, Math.ceil(list.length / PAGE));
      note.innerHTML = 'Showing ' + list.length + ' posts, excluding the archive. <a href="/">Show all posts</a>';

      function render(page, push) {
        page = Math.min(Math.max(1, page), pages);
        var items = list.slice((page - 1) * PAGE, page * PAGE);
        return Promise.all(items.map(loadThumb)).then(function (thumbs) {
          grid.innerHTML = items.map(function (e, i) { return card(e, thumbs[i]); }).join('');
          pager.innerHTML = pagerHtml(page, pages);
          if (push) {
            history.pushState({ page: page }, '', '?posts=current' + (page > 1 ? '&page=' + page : ''));
            note.scrollIntoView({ behavior: 'smooth', block: 'start' });
          }
        });
      }

      pager.addEventListener('click', function (ev) {
        var a = ev.target.closest('a[data-page]');
        if (!a) return;
        ev.preventDefault();
        render(parseInt(a.getAttribute('data-page'), 10), true);
      });
      window.addEventListener('popstate', function () {
        render(parseInt(new URLSearchParams(location.search).get('page'), 10) || 1, false);
      });
      render(parseInt(params.get('page'), 10) || 1, false);
    }).catch(function () {
      note.innerHTML = 'Could not load posts. <a href="/">Show all posts</a>';
    });
  }

  // ----- Profile button: About / Contact (replaces the footer menu) -----
  function setupProfileMenu() {
    var host = document.querySelector('#header-wrap .container');
    if (!host || document.querySelector('.profile-menu')) return;
    var icon = function (d) { return '<svg viewBox="0 0 24 24">' + d + '</svg>'; };
    var wrap = document.createElement('div');
    wrap.className = 'profile-menu';
    wrap.innerHTML =
      '<button type="button" class="profile-btn" aria-haspopup="true" aria-expanded="false" aria-label="Open profile menu"><img src="https://cdn.jsdelivr.net/gh/ten-choi/blog-images@main/dev/avatar_ten.webp" alt="" width="32" height="32"/><span class="pb-name">Ten</span><svg class="pb-caret" viewBox="0 0 24 24"><path d="M6 9l6 6 6-6"/></svg></button>' +
      '<div class="profile-card" role="menu">' +
        '<p class="pc-name">Ten</p>' +
        '<p class="pc-role">Backend developer, product engineer in progress</p>' +
        '<ul class="pc-links">' +
          '<li><a href="/p/about.html" role="menuitem">' + icon('<circle cx="12" cy="8" r="4"/><path d="M4 21c0-4 4-7 8-7s8 3 8 7"/>') + 'About</a></li>' +
          '<li><a href="/p/contact.html" role="menuitem">' + icon('<rect x="3" y="5" width="18" height="14" rx="2"/><path d="M3 7l9 6 9-6"/>') + 'Contact</a></li>' +
          '<li><a href="/p/blog-history.html" role="menuitem">' + icon('<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 3"/>') + 'Blog History</a></li>' +
        '</ul>' +
      '</div>';
    host.appendChild(wrap);
    var btn = wrap.querySelector('.profile-btn');
    function setOpen(open) {
      wrap.classList.toggle('open', open);
      btn.setAttribute('aria-expanded', open ? 'true' : 'false');
    }
    btn.addEventListener('click', function (e) { e.stopPropagation(); setOpen(!wrap.classList.contains('open')); });
    document.addEventListener('click', function (e) { if (!wrap.contains(e.target)) setOpen(false); });
    document.addEventListener('keydown', function (e) { if (e.key === 'Escape') setOpen(false); });
  }

  // ----- Comments: full-page fallback when the embedded form can't sign in -----
  // The embedded comment form is a blogger.com iframe; browsers that block
  // third-party cookies (Brave, Chrome tracking protection) show it as signed
  // out. Blogger's full-page comment form runs first-party and works there.
  function setupCommentFallback() {
    var src = document.getElementById('comment-editor-src');
    var form = document.querySelector('.comment-form');
    if (!src || !form || form.querySelector('.comment-fallback')) return;
    var m = /\/comment\/frame\/(\d+)\?(?:.*&)?po=(\d+)/.exec(src.getAttribute('href') || '');
    if (!m) return;
    var url = 'https://www.blogger.com/comment/fullpage/post/' + m[1] + '/' + m[2];
    var p = document.createElement('p');
    p.className = 'comment-fallback';
    p.innerHTML = 'Can’t sign in above? Your browser may be blocking Blogger cookies. ' +
      '<a href="' + url + '" target="_blank" rel="noopener">Write your comment on Blogger ↗</a>';
    form.appendChild(p);
  }

  function groupHeaderActions() {
    var host = document.querySelector('#header-wrap .container');
    var toggle = document.querySelector('.theme-toggle');
    var profile = document.querySelector('.profile-menu');
    if (!host || !toggle || !profile || document.querySelector('.header-actions')) return;
    var box = document.createElement('div');
    box.className = 'header-actions';
    box.appendChild(toggle);
    box.appendChild(profile);
    host.appendChild(box);
  }

  function init() {
    setupThemeToggle();
    setupProfileMenu();
    groupHeaderActions();
    setupCommentFallback();
    setupTags();
    setupMyStats();
    setupFilterView();
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init); else init();
})();
//
